"""Regenerate the standalone design specimens; no production files are changed."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parent
ASSETS = ROOT / 'assets'


def svg(name, contents, background, view='0 0 600 400'):
    (ASSETS / f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{view}"><rect width="100%" height="100%" fill="{background}"/>{contents}</svg>')


svg('orbit', '<g fill="none" stroke="#798baa" stroke-width="1"><ellipse cx="300" cy="200" rx="235" ry="75" transform="rotate(-30 300 200)"/><ellipse cx="300" cy="200" rx="220" ry="100" transform="rotate(35 300 200)"/><circle cx="300" cy="200" r="150"/><path d="M40 200H560M300 25V375" stroke-dasharray="3 8"/></g><circle cx="300" cy="200" r="64" fill="#c7b8ff"/><path d="M300 147V253M247 200H353M262 162L338 238M262 238L338 162" stroke="#263955" stroke-width="5"/><circle cx="477" cy="107" r="18" fill="#e5b69d"/><circle cx="157" cy="315" r="12" fill="#d8e7a5"/><circle cx="118" cy="104" r="4" fill="#e6e8f1"/><circle cx="508" cy="286" r="4" fill="#e6e8f1"/>', '#1d2c45')
svg('botanical', '<circle cx="300" cy="205" r="167" fill="#e4e9d4"/><g fill="none" stroke="#426957" stroke-width="3"><path d="M300 343C291 270 345 211 290 88M300 289C238 245 220 206 196 164M306 266C370 239 395 206 414 165"/><path d="M291 185C257 172 244 150 247 114M310 231C346 205 356 168 355 140"/></g><g fill="#738968"><path d="M286 147Q222 144 229 92Q279 96 286 147Z"/><path d="M300 182Q345 164 340 115Q291 128 300 182Z"/><path d="M289 249Q233 247 230 203Q278 202 289 249Z"/><path d="M305 299Q358 301 378 261Q325 248 305 299Z"/><path d="M198 170Q153 161 159 119Q200 127 198 170Z"/><path d="M402 185Q439 178 452 135Q413 127 402 185Z"/></g><g fill="#c96e54"><circle cx="289" cy="84" r="21"/><circle cx="253" cy="108" r="15"/><circle cx="352" cy="133" r="17"/><circle cx="195" cy="157" r="14"/><circle cx="418" cy="159" r="16"/></g><g fill="#e9b866"><circle cx="289" cy="84" r="7"/><circle cx="352" cy="133" r="6"/></g><path d="M252 334H348L335 387H265Z" fill="#af5b42"/><path d="M246 334H354" stroke="#6d4937" stroke-width="4"/><g stroke="#b5bba8" stroke-width="1" fill="none"><path d="M45 70H165M435 70H555M65 340H185M430 334H544"/><circle cx="87" cy="285" r="17"/><path d="M493 226l8 15 17 3-12 12 2 17-15-8-15 8 3-17-13-12 17-3Z"/></g>', '#fff5e7')
svg('paths', '<g fill="none" stroke="#a4b19a" stroke-width="2">'+''.join(f'<path d="M-40 {i*28}C130 {i*28-80} 175 {i*28+130} 350 {i*28+35}S520 {i*28-70} 660 {i*28+20}"/>' for i in range(16))+'</g><path d="M95 345C180 300 130 235 245 230S298 135 420 145S420 80 515 55" fill="none" stroke="#704d32" stroke-width="5" stroke-dasharray="8 8"/><circle cx="95" cy="345" r="10" fill="#ab593e"/><circle cx="515" cy="55" r="10" fill="#ab593e"/><g fill="#3c5848"><path d="M330 255l35 65h-70Z"/><path d="M385 270l27 50h-54Z"/></g>', '#e0e4ce')
svg('shapes', '<circle cx="155" cy="200" r="125" fill="#c56951"/><rect x="258" y="70" width="215" height="260" rx="105" fill="#334960"/><path d="M140 327L330 80L520 327Z" fill="#e9bc66" fill-opacity=".92"/><g fill="none" stroke="#f7f0e3" stroke-width="2">'+''.join(f'<circle cx="365" cy="204" r="{i}"/>' for i in range(25,151,18))+'</g>', '#e7dfd0')
svg('books', '<g transform="rotate(-10 300 200)"><rect x="107" y="104" width="280" height="200" rx="5" fill="#d09b65"/><rect x="144" y="85" width="280" height="210" rx="5" fill="#e9e2ca" stroke="#32584f" stroke-width="2"/><path d="M284 87V293M165 113Q222 102 262 119M307 119Q357 101 402 110M167 137H263M307 137H400M167 160H263M307 160H400M167 183H263M307 183H400M167 206H263M307 206H400" stroke="#7f9786" stroke-width="3"/><path d="M355 85V167L371 156L387 167V85" fill="#ba6555"/></g><circle cx="490" cy="280" r="46" fill="#9bad8e"/><circle cx="490" cy="280" r="33" fill="#425f50"/><path d="M525 263Q566 266 525 299" stroke="#9bad8e" fill="none" stroke-width="11"/>', '#e6e9d4')

DESIGNS = {
    'edition': ('01', 'The Sunday Edition', 'Editorial / layered / assured'),
    'field': ('02', 'Field Notes', 'Photographic / tactile / personal'),
    'cabinet': ('03', 'The Curiosity Cabinet', 'Illustrated / warm / exploratory'),
    'afterhours': ('04', 'After Hours', 'Dark / colourful / playful'),
}
POSTS = [
    ('life', 'On taking the long way', 'A small case for wandering, paying attention, and arriving a little later.', '18 September 2026', '6 min read', 'harbour.jpg'),
    ('making', 'Making things for the joy of it', 'Not every project needs a business plan. Some just need an afternoon.', '10 September 2026', '4 min read', 'shapes.svg'),
    ('ideas', 'A notebook is a place to change your mind', 'Keeping a thought around long enough to see what it might become.', '02 September 2026', '5 min read', 'books.svg'),
]


def art(name, label=''):
    return f'<img class="art" src="assets/{name}.svg" alt="{escape(label)}" width="600" height="400">'


def link(kind, index=0):
    return f'{kind}-post.html' + (f'?sample={index}' if index else '')


def filters():
    return '<div class="filterbar" aria-label="Filter writing">'+''.join(f'<button data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{label}</button>' for key,label in [('all','Everything'),('life','Life'),('making','Making'),('ideas','Ideas')])+'</div><p class="sr-only" role="status" data-filter-status></p>'


def head(kind, article=False):
    number,name,_=DESIGNS[kind]
    brand={'edition':'Santiago Mooser','field':'Santiago’s field notes','cabinet':'<span class="brand-symbol" aria-hidden="true">✳</span>Santiago Mooser','afterhours':'<span class="brand-mark" aria-hidden="true">s.</span>Santiago Mooser'}[kind]
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>{name}{' · Reading' if article else ''} — Santiago</title><link rel="stylesheet" href="style.css"><script src="ui.js" defer></script></head><body class="{kind}"><a class="skip" href="#main">Skip to content</a><div class="studybar"><span>ROUND 02 · {number} / {name} · Illustrative content</span><a href="index.html">Compare four directions ↗</a></div><div class="wrap"><header class="site-header"><a class="brand" href="{kind}.html">{brand}</a><nav class="site-nav" aria-label="Main"><a href="{kind}.html#writing">Writing</a><a href="{kind}.html#notes">Notes</a><a href="#about">About</a></nav></header>'''


def footer(kind):
    return f'''<footer id="about" class="about"><div><h2>A little corner, entirely my own.</h2><p>I’m Santiago. This is a place for things I’m thinking about, things I’m making, and the occasional detour.</p><a href="../static/cv.pdf">The professional version: my CV ↗</a><small>Design specimen. Biography, post titles and prose are proposed sample copy, not published statements.</small></div><div class="right"><a href="#main">Back to top ↑</a><small>Photography: <a href="https://unsplash.com/photos/modern-cityscape-across-a-wide-blue-ocean-B1T0D56Zq9w">I P / Unsplash</a> · Original vector illustrations</small><small>Made for reading. Room for everything else.</small></div></footer></div></body></html>'''


def card(kind,index,extra=''):
    topic,title,desc,date,read,image=POSTS[index]
    visual = f'<img src="assets/{image}" alt="Hong Kong’s waterfront across Victoria Harbour" width="1800" height="1200">' if image.endswith('.jpg') else art(image[:-4])
    if kind=='afterhours' and index==0: visual=art('paths')
    return f'''<article class="post-card {extra}" data-topic="{topic}"><div class="{'small-art' if kind=='edition' else 'card-image'}">{visual}</div><div class="card-body"><span class="mono">{topic} / {read}</span><h3><a href="{link(kind,index)}">{title}</a></h3><p>{desc}</p><span class="mono muted">{date}</span></div></article>'''


edition = '''<div class="masthead"><div class="masthead-name">The Sunday Edition.</div><div class="masthead-note">A personal journal of ideas,<br>observations & other things.</div></div><div class="issue-line mono"><span>By Santiago Mooser</span><span>Independent thoughts · No particular niche</span><span>Vol. 01 / 2026</span></div><main id="main"><section class="feature"><div class="feature-copy"><span class="kicker">The latest essay / Life</span><h1>On taking<br>the long way.</h1><p>A small case for wandering, paying attention, and arriving a little later.</p><a class="read-link" href="edition-post.html">Read the essay <span>↗</span></a><div class="stamp">TAKE<br>YOUR<br>TIME</div></div><figure class="feature-image"><img src="assets/harbour.jpg" alt="Hong Kong skyline seen from the water" width="1800" height="1200"><figcaption>A change of perspective. Victoria Harbour, Hong Kong.<br>Photo: I P / Unsplash</figcaption></figure><aside id="notes" class="side-notes"><h2>In the margins</h2><div class="side-note"><span class="mono muted">A small thought</span><a href="edition-post.html?sample=2">You don’t have to turn every interest into a project.</a></div><div class="side-note"><span class="mono muted">From the notebook</span><a href="edition-post.html?sample=1">Good tools leave room for improvisation.</a></div><span class="mono muted">Fragments worth keeping.</span></aside></section><section id="writing"><div class="section-head"><h2>Elsewhere in the notebook</h2><span class="mono">Life / Making / Ideas</span></div>FILTERS<div class="stories">CARDS</div></section></main>'''.replace('FILTERS',filters()).replace('CARDS',''.join(card('edition',i) for i in [1,2,0]))
field = '''<main id="main"><section class="field-cover"><img src="assets/harbour.jpg" alt="Wide view of Hong Kong’s waterfront and blue harbour" width="1800" height="1200"><div class="cover-stamp">NOT ALL<br>WANDERING<br>IS LOST TIME</div><div class="cover-content"><span class="mono">A journal by Santiago Mooser</span><h1>The world is<br>better on foot.</h1><p>Places, passing thoughts, and the things you only notice when you slow down.</p><a class="read-link" href="field-post.html">On taking the long way <span>↗</span></a></div><div class="cover-bottom"><span>FIELD NOTE 001 — HONG KONG</span><span>18 SEPTEMBER 2026 · 6 MIN READ</span></div></section><section id="notes" class="intro-strip"><span class="mono">Collected along the way</span><p>A little technology. A little everyday life.<br>A lot of curiosity about both.</p><a class="read-link" href="#writing">Open the notebook ↓</a></section><section id="writing"><div class="section-head"><h2>Recent entries</h2><span class="mono">Notes from here & there</span></div>FILTERS<div class="field-stories">CARDS</div></section></main>'''.replace('FILTERS',filters()).replace('CARDS',''.join(card('field',i) for i in range(3)))
cabinet = '''<main id="main"><section class="cabinet-intro"><div><span class="kicker">Welcome to my curiosity cabinet</span><h1>A few things<br>on my <em>mind.</em></h1><p>Ideas to turn over. Things to try. Small discoveries to keep. I’m Santiago, and this is where I put them.</p><a class="read-link" href="#writing">Have a look around <span>↓</span></a></div><div class="cabinet-visual">ART<span class="annotation">always a work in progress ↗</span></div></section><section id="writing"><div class="section-head"><h2>Growing thoughts</h2><span class="mono">Follow a thread</span></div>FILTERS<div class="cabinet-layout"><div class="cabinet-cards">CARDS</div><aside id="notes" class="shelf"><img class="avatar" src="../static/profile.jpg" alt="Santiago" width="64" height="64"><h2>The little shelf</h2><p>Not everything needs to become an essay.</p><hr><span class="kicker">A thought to keep</span><p>“What would I make if nobody was keeping score?”</p><hr><a href="cabinet-post.html?sample=2">Open a notebook entry ↗</a><p class="sample-notice">Illustrative shelf content</p></aside></div></section></main>'''.replace('ART',art('botanical')).replace('FILTERS',filters()).replace('CARDS',''.join(card('cabinet',i) for i in [2,1,0]))
afterhours = '''<main id="main"><section class="night-intro"><div><span class="status">A personal space on the internet</span><h1>Thinking<br>in the <span>open.</span></h1><p>Life, side quests, and ideas that won’t leave me alone. A notebook by Santiago Mooser.</p><a class="read-link" href="afterhours-post.html">Start with the latest essay <span>↗</span></a></div><div class="orbit-panel">ART<span class="orbit-caption">FOLLOW YOUR CURIOSITY ↗</span></div></section><section id="writing"><div class="section-head"><h2>Fresh from the notebook</h2><span class="mono muted">03 entries / All welcome</span></div>FILTERS<div class="night-cards">CARDS</div></section><aside id="notes" class="note-strip"><span class="mono">A passing thought ↗</span><p>Sometimes the most useful thing you can build is something that makes you smile.</p><a href="afterhours-post.html?sample=1">Read on →</a></aside></main>'''.replace('ART',art('orbit')).replace('FILTERS',filters()).replace('CARDS',''.join(card('afterhours',i) for i in range(3)))

for kind,body in [('edition',edition),('field',field),('cabinet',cabinet),('afterhours',afterhours)]:
    (ROOT/f'{kind}.html').write_text(head(kind)+body+footer(kind))

prose = '''<div class="prose"><p>I used to think of a walk as the space between two places. A way of getting somewhere, preferably without taking too long. There was always a quicker route, and usually a reason to take it.</p><p>Then there are the days when the route becomes the point. A turn you have never taken. A familiar street at an unfamiliar hour. The small pleasure of finding yourself somewhere you did not plan to be.</p><h2 id="attention">A different kind of attention</h2><p>Moving a little more slowly changes what is available to notice. The city stops being a diagram of destinations and becomes a collection of details: a half-open window, a conversation, light moving across the water.</p><blockquote>Some things only become visible when you stop trying to get past them.</blockquote><p>I think the same is true of ideas. When everything has to become useful immediately, there is very little room for an uncertain thought to grow into something interesting.</p><h2 id="detours">Making room for detours</h2><p>A notebook gives those thoughts somewhere to live. A place to write something down without having to explain why it deserves to be there.</p><p>It might become an essay later. It might become a project. It might remain a paragraph that reminds you of an afternoon. All three seem like good outcomes.</p><h2 id="keeping">Something worth keeping</h2><p>That is the kind of space I want this to be. A few longer thoughts, a few small discoveries, and enough room to change my mind.</p><p>For now, I am going to take the long way home.</p><p class="sample-notice">Illustrative article written for this design study, not a published post by Santiago. All homepage titles open this same specimen.</p></div>'''
for kind in DESIGNS:
    kicker='<span class="kicker">Life / Field note 001</span>' if kind!='field' else '<span class="mono">Life / Field note 001</span>'
    visual = '<div class="article-art">'+art('botanical' if kind=='cabinet' else 'orbit')+'</div>' if kind in ['cabinet','afterhours'] else ''
    hero=f'<div><a class="back" href="{kind}.html#writing">← Back to writing</a><br>{kicker}<h1>On taking<br>the long way.</h1><p class="article-deck">A small case for wandering, paying attention, and arriving a little later.</p><p class="article-meta">Santiago Mooser · 18 September 2026 · 6 min read</p></div>{visual}'
    cover='<img class="article-cover" src="assets/harbour.jpg" alt="Hong Kong skyline across Victoria Harbour" width="1800" height="1200"><p class="caption">Victoria Harbour, Hong Kong · Photo by I P / Unsplash</p>' if kind in ['edition','field'] else ''
    aside='<aside aria-label="On this page"><span class="mono">In this essay</span><a href="#attention">01 / Attention</a><a href="#detours">02 / Detours</a><a href="#keeping">03 / Keeping</a><p class="muted">A little room<br>to wander.</p></aside>'
    body=f'<main id="main"><section class="article-hero">{hero}</section>{cover}<div class="article-grid">{aside}{prose}</div><a class="top-link" href="{kind}.html#writing">← More from the notebook</a></main>'
    (ROOT/f'{kind}-post.html').write_text(head(kind,True)+body+footer(kind))

print('Generated four homepages, four reading specimens, and five original SVG illustrations.')
